references.example:
#include <ranges>
#include <string>
#include <string_view>

static_assert(std::ranges::borrowed_range<std::string&>);
static_assert(!std::ranges::borrowed_range<std::string>);
static_assert(std::ranges::borrowed_range<std::string_view>);
// Последнее не разрешает читать string_view после гибели его данных.
